import Supermemory from "supermemory";

const client = new Supermemory({
  apiKey: process.env.SUPERMEMORY_API_KEY,
});

const doc = await client.add({
  content: "Sarah is being promoted to VP of Product.",
  containerTag: "user_123",
  customId: "chat_session_1",
  metadata: { type: "conversation" },
  dreaming: "instant",
});

console.log(doc.id, doc.status); // queued → poll until done

import Supermemory from "supermemory";

const client = new Supermemory({
  apiKey: process.env.SUPERMEMORY_API_KEY,
});

const res = await client.documents.batchAdd({
  documents: [
    {
      content: "Q3 roadmap notes",
      containerTag: "user_123",
      customId: "doc_roadmap",
    },
    {
      content: "Gift policy for VP promotions",
      containerTag: "user_123",
      customId: "doc_gifts",
    },
  ],
});
console.log(res);

from supermemory import Supermemory

client = Supermemory()  # uses SUPERMEMORY_API_KEY

res = client.documents.batch_add(
    documents=[
        {
            "content": "Q3 roadmap notes",
            "container_tag": "user_123",
            "custom_id": "doc_roadmap",
        },
        {
            "content": "Gift policy for VP promotions",
            "container_tag": "user_123",
            "custom_id": "doc_gifts",
        },
    ],
)
print(res)

