import Supermemory from "supermemory";

const client = new Supermemory({
  apiKey: process.env.SUPERMEMORY_API_KEY,
});

const { profile } = await client.profile({
  containerTag: "user_123",
});

console.log(profile.static);  // long-term facts
console.log(profile.dynamic); // recent context

import Supermemory from "supermemory";

const client = new Supermemory({
  apiKey: process.env.SUPERMEMORY_API_KEY,
});

const res = await fetch("https://api.supermemory.ai/v4/profile/buckets", {
  method: "POST",
  headers: {
    Authorization: `Bearer ${process.env.SUPERMEMORY_API_KEY}`,
    "Content-Type": "application/json",
  },
  body: JSON.stringify({ containerTag: "user_123" }),
});
const data = await res.json();
console.log(data);

import Supermemory from "supermemory";

const client = new Supermemory({
  apiKey: process.env.SUPERMEMORY_API_KEY,
});

const results = await client.search.memories({
  q: "gift ideas for a VP promotion after a Tokyo offsite",
  containerTag: "user_123",
  searchMode: "hybrid", // memories | documents | hybrid
  limit: 5,
  include: { relatedMemories: true },
});

for (const hit of results.results) {
  console.log(hit.memory ?? hit.chunk, hit.similarity);
}

